/**
 * Oracle parity for the crq repair harvest outcome policy.
 *
 * The fixture is generated by `apps/crq-python/repair_harvest_vectors.py`,
 * which drives the PRODUCTION `repair_tick.harvest` ->
 * `mark_finding_outcome` -> `finding_delivery.Inbox.repair_outcome` over a
 * real temporary inbox/outbox. These tests compare the TS planner's canonical
 * event, row, action and failure class byte-for-byte with that output.
 *
 * The `invalid-fixed-without-commits` case belongs to the harvest loop's
 * artifact validation (a FIXED result without commits is rejected before any
 * outcome is planned); the typed `review.fixFinding` contract cannot emit it,
 * so it is asserted as a Python-only validation case here.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import {
  planRepairHarvest,
  type RepairHarvestFailureClass,
  type RepairHarvestVerdict,
} from '../../../src/policy/crq/repairHarvest.js';
import {
  JsonNumber,
  JsonObject,
  parseJsonValue,
  toPlainJson,
  type JsonValue,
} from '../../../src/policy/crq/jsonValue.js';

const FIXTURE_URL = new URL(
  '../../../apps/crq-python/fixtures/repair-harvest/cases.json',
  import.meta.url,
);
const fixture = asObject(parseJsonValue(readFileSync(FIXTURE_URL, 'utf8')));
const harvestCases = asArray(fixture.get('harvest_cases')).map(asObject);
const markCases = asArray(fixture.get('mark_cases')).map(asObject);

function asObject(value: JsonValue | undefined): JsonObject {
  if (!(value instanceof JsonObject)) throw new Error('fixture value is not an object');
  return value;
}

function asArray(value: JsonValue | undefined): JsonValue[] {
  if (!Array.isArray(value)) throw new Error('fixture value is not an array');
  return value;
}

function string(value: JsonValue | undefined): string {
  if (typeof value !== 'string') throw new Error('fixture value is not a string');
  return value;
}

function item(values: JsonValue[], index: number): JsonValue {
  const value = values[index];
  if (value === undefined) throw new Error('fixture array item missing');
  return value;
}

function integer(value: JsonValue | undefined): number {
  if (!(value instanceof JsonNumber) || value.integer === null) {
    throw new Error('fixture value is not an integer');
  }
  return Number(value.integer);
}

const AT = string(fixture.get('at'));
const FINDING_ID = string(fixture.get('finding_id'));
const JOB = string(fixture.get('job'));
const MAX_RETRIES = integer(fixture.get('max_finding_retries'));
const REPAIR_BASE = string(fixture.get('repair_base'));
const SKIP = new Set(['invalid-fixed-without-commits']);

function failureClass(value: JsonValue | undefined): RepairHarvestFailureClass {
  const text = string(value);
  switch (text) {
    case 'transient':
    case 'exhausted':
    case 'evidence':
    case 'protected-path':
    case 'owner-decision':
      return text;
    default:
      return 'exhausted';
  }
}

function evidence(value: JsonValue | undefined): Array<{ path: string; line: number }> {
  return asArray(value).map((entry) => {
    const row = asObject(entry);
    return { path: string(row.get('path')), line: integer(row.get('line')) };
  });
}

/** The caller's typed derivation from a Python repair result, as crq does. */
function verdictOf(outcome: JsonObject): RepairHarvestVerdict {
  const verdict = string(outcome.get('verdict'));
  if (verdict === 'FIXED') {
    return { verdict: 'fixed', commits: asArray(outcome.get('commits')).map(string) };
  }
  if (verdict === 'NOT-FIXED') {
    return {
      verdict: 'not-fixed',
      evidence: evidence(outcome.get('unchanged_evidence') ?? []),
      failureClass: failureClass(outcome.get('failure_class') ?? 'exhausted'),
    };
  }
  if (verdict === 'FAILED') {
    return {
      verdict: 'failed',
      failureClass: failureClass(outcome.get('failure_class')),
      reason: string(outcome.get('reason')),
    };
  }
  return { verdict: 'stale', reason: string(outcome.get('reason')) };
}

describe('repair harvest oracle parity', () => {
  test('fixture shape and case names', () => {
    expect(string(fixture.get('schema'))).toBe('cq.crq-repair-harvest-vector/v1');
    expect(harvestCases.length).toBeGreaterThanOrEqual(17);
    const names = harvestCases.map((entry) => string(entry.get('name')));
    expect(new Set(names).size).toBe(names.length);
    expect(names).toContain('failed-owner-decision');
    expect(names).toContain('retry-bound-reached');
    expect(names).toContain('idempotent-replay-after-spool');
  });

  for (const entry of harvestCases) {
    const name = string(entry.get('name'));
    const retained = asArray(entry.get('retained_before'));
    const events = asArray(entry.get('events_added'));
    const rowBefore = asObject(entry.get('row_before'));
    const rowAfter = asObject(entry.get('row_after'));

    test(`harvest case: ${name}`, () => {
      if (SKIP.has(name)) {
        // Python rejects the malformed artifact inside `harvest`, persists
        // queue identity, then records a terminal FAILED whose reason is the
        // Python exception prose. The TS seam consumes read-validated
        // artifacts, so parity here covers the D7 action/class only; the
        // reason bytes belong to the caller/queue slice.
        expect(events).toHaveLength(1);
        const payload = asObject(asObject(events[0]).get('payload'));
        expect(string(payload.get('action'))).toBe('needs-retriage');
        expect(string(asObject(payload.get('evidence')).get('failure_class'))).toBe('exhausted');
        return;
      }
      const plan = planRepairHarvest({
        row: rowBefore,
        findingId: FINDING_ID,
        job: JOB,
        verdict: verdictOf(asObject(entry.get('outcome'))),
        reason: string(asObject(entry.get('outcome')).get('reason')),
        at: AT,
        maxFindingRetries: MAX_RETRIES,
        retained,
        repairBase: REPAIR_BASE,
      });
      if (events.length === 0) {
        expect(plan.kind, name).toBe('none');
        expect(toPlainJson(rowBefore), name).toEqual(toPlainJson(rowAfter));
        return;
      }
      expect(plan.kind, name).toBe('write');
      if (plan.kind !== 'write') return;
      expect(toPlainJson(plan.event), name).toEqual(toPlainJson(item(events, 0)));
      expect(toPlainJson(plan.row), name).toEqual(toPlainJson(rowAfter));
      expect(plan.action, name).toBe(
        string(asObject(asObject(item(events, 0)).get('payload')).get('action')),
      );
    });
  }

  test('replay sees the canonical outcome already retained', () => {
    const entry = asObject(
      harvestCases.find((value) => string(value.get('name')) === 'idempotent-replay-after-spool'),
    );
    const retained = [
      ...asArray(entry.get('retained_before')),
      ...asArray(entry.get('events_added')),
    ];
    const plan = planRepairHarvest({
      row: asObject(entry.get('row_before')),
      findingId: FINDING_ID,
      job: JOB,
      verdict: verdictOf(asObject(entry.get('outcome'))),
      reason: string(asObject(entry.get('outcome')).get('reason')),
      at: AT,
      maxFindingRetries: MAX_RETRIES,
      retained,
      repairBase: REPAIR_BASE,
    });
    expect(plan.kind).toBe('already-recorded');
    if (plan.kind === 'already-recorded') expect(plan.action).toBe('needs-retriage');
  });

  for (const entry of markCases) {
    const name = string(entry.get('name'));
    test(`mark case: ${name}`, () => {
      const merge = entry.get('merge');
      const plan = planRepairHarvest({
        row: asObject(entry.get('row_before')),
        findingId: FINDING_ID,
        job: JOB,
        verdict: verdictOf(asObject(entry.get('outcome'))),
        reason: string(asObject(entry.get('outcome')).get('reason')),
        at: AT,
        maxFindingRetries: MAX_RETRIES,
        retained: asArray(entry.get('retained_before')),
        repairBase: REPAIR_BASE,
        fixPr: 7,
        ...(typeof merge === 'string' ? { mergedCommit: merge } : {}),
      });
      const events = asArray(entry.get('events_added'));
      if (events.length === 0) {
        expect(plan.kind).toBe('none');
        if (plan.kind === 'none') expect(plan.reason).toBe('fixed-requires-merge');
        return;
      }
      expect(plan.kind).toBe('write');
      if (plan.kind !== 'write') return;
      expect(toPlainJson(plan.event)).toEqual(toPlainJson(item(events, 0)));
      expect(toPlainJson(plan.row)).toEqual(toPlainJson(asObject(entry.get('row_after'))));
    });
  }

  test('an incomplete retained chain refuses instead of guessing the retry bound', () => {
    const first = harvestCases[0];
    if (first === undefined) throw new Error('fixture has no harvest cases');
    const plan = planRepairHarvest({
      row: asObject(first.get('row_before')),
      findingId: FINDING_ID,
      job: JOB,
      verdict: { verdict: 'failed', failureClass: 'exhausted', reason: 'x' },
      reason: 'x',
      at: AT,
      maxFindingRetries: MAX_RETRIES,
      retained: [],
      repairBase: REPAIR_BASE,
    });
    expect(plan).toEqual({ kind: 'refused', refusal: 'retry-history-incomplete' });
  });

  test('a missing review id or previous event id refuses typed', () => {
    const row = new JsonObject([
      ['status', 'delivered'],
      ['receipt', new JsonObject([['repair_task', JOB]])],
    ]);
    const input = {
      row,
      findingId: FINDING_ID,
      job: JOB,
      verdict: { verdict: 'failed', failureClass: 'exhausted', reason: 'x' } as const,
      reason: 'x',
      at: AT,
      maxFindingRetries: MAX_RETRIES,
      retained: [] as JsonValue[],
    };
    expect(planRepairHarvest(input)).toEqual({
      kind: 'refused',
      refusal: 'finding-row-missing-review-id',
    });
    const withReview = new JsonObject([...row.entries, ['review_id', 'b'.repeat(64)]]);
    expect(planRepairHarvest({ ...input, row: withReview })).toEqual({
      kind: 'refused',
      refusal: 'finding-row-missing-previous-event-id',
    });
  });
});
